/**
 * Typed client for the backend. Types come from the API's own schema (schema.ts, generated by
 * `npm run api:types` while the API is running), so the frontend cannot drift from it.
 * All timestamps are UTC strings; pass `asOf` to view the dashboard at a past moment.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];

export type Meta = Schemas["Meta"];
export type Forecast = Schemas["Forecast"];
export type Changes = Schemas["Changes"];
export type Actuals = Schemas["Actuals"];
export type Alerts = Schemas["Alerts"];
export type Performance = Schemas["Performance"];

type Query = Record<string, string | undefined>;

async function get<T>(path: string, query: Query = {}): Promise<T> {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value !== undefined) params.set(key, value);
  }
  const text = params.toString();
  const response = await fetch(text ? `${path}?${text}` : path);
  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as { detail?: unknown } | null;
    throw new Error(typeof body?.detail === "string" ? body.detail : `${path} returned ${response.status}`);
  }
  return (await response.json()) as T;
}

export const getMeta = () => get<Meta>("/api/meta");
export const getForecast = (asOf?: string) => get<Forecast>("/api/forecast", { as_of: asOf });
export const getChanges = (asOf?: string) => get<Changes>("/api/changes", { as_of: asOf });
export const getAlerts = (asOf?: string) => get<Alerts>("/api/alerts", { as_of: asOf });
export const getActuals = (asOf?: string, from?: string, to?: string) =>
  get<Actuals>("/api/actuals", { as_of: asOf, from, to });
export const getPerformance = (asOf?: string, from?: string, to?: string) =>
  get<Performance>("/api/performance", { as_of: asOf, from, to });
